// Returns a bitmask of the table's spheres that no listed object touches, testing swept offsets.
int compute_clear_path_point_mask(int *objs, int n, int idx, float f, float *pos) {
    char *t = novalis_paths[idx];
    int mask = 0;
    int k;
    int j;
    int found;
    float v[4];
    float w1[4];
    float w2[4];
    float zv[4];

    float fz = f;
    for (k = 0; k < *(int *)t; k++) {
        found = 0;
        for (j = 0; j < n; j++) {
            if (fz != 0.0f) {
                char *e = t + (k * 16 + 0x10);
                *(u128 *)zv = 0;
                zv[2] = 1.0f;
                FastVecSub(v, pos, e);
                FastVecCross(v, v, zv);
                vec_scale_to_length(v, v, fz);
                FastVecSub(w1, pos, v);
                FastVecAdd(w2, pos, v);
                if (test_path_segment_strict_crossing(objs[j], w1, e) != 0) {
                    found = 1;
                } else if (test_path_segment_strict_crossing(objs[j], w2, e) != 0) {
                    found = 1;
                }
            } else {
                if (test_path_segment_strict_crossing(objs[j], pos, t + (k * 16 + 0x10)) != 0)
                    found = 1;
            }
            if (found)
                break;
        }
        if (!found)
            mask |= 1 << k;
    }
    return mask;
}

// Expands a bit mask through a table of per-bit masks until it meets another mask.
int expand_path_mask_to_intersection(int idx, int a, int mask) {
    char *p = novalis_paths[idx];
    int i;
    int j;
    int m;
    for (i = 0; i < 32; i++) {
        if (a & mask) {
            return a & mask;
        }
        m = mask;
        for (j = 0; j < 32; j++) {
            if ((mask >> j) & 1) {
                m |= *(int *)(p + 0x1C + j * 16);
            }
        }
        mask = m;
    }
    return 0;
}
